R=[
(2194,"क्रैनबेरी मफिन","DaVita की आहार विशेषज्ञ बोनी (टेक्सस) की यह क्रैनबेरी मफिन रेसिपी, उन्हें Better Homes and Garden® Cookbook में मिली एक रेसिपी को किडनी आहार के अनुसार बदलकर बनाई गई है।","12","1 मफिन",
["1-3/4 कप + 3 बड़े चम्मच मैदा","3 बड़े चम्मच ब्राउन शुगर","1/4 छोटा चम्मच पिसी दालचीनी","2 बड़े चम्मच मक्खन","7 बड़े चम्मच चीनी","2 छोटे चम्मच बेकिंग पाउडर","1/4 छोटा चम्मच नमक","1 अंडा, फेंटा हुआ","3/4 कप क्रैनएप्पल जूस","1/4 कप खाना पकाने का तेल","1 कप ताज़ी या जमी हुई क्रैनबेरी, मोटी कटी हुई"],
["ओवन को 400° F पर पहले से गरम करें। 2-1/2″ के बारह मफिन कपों में चिकनाई लगाएँ या उनमें बेकिंग कप लगाएँ; एक तरफ़ रख दें।","स्ट्रूज़ल टॉपिंग बनाने के लिए एक कटोरे में 3 बड़े चम्मच मैदा, ब्राउन शुगर और दालचीनी मिलाएँ। 2 बड़े चम्मच मक्खन को तब तक मिलाएँ जब तक मिश्रण मोटे चूरे जैसा न हो जाए; एक तरफ़ रख दें।","मफिन बनाने के लिए एक मध्यम कटोरे में बचा हुआ मैदा, चीनी, बेकिंग पाउडर और नमक मिलाएँ। मैदे के मिश्रण के बीच में गड्ढा बनाएँ; एक तरफ़ रख दें।","दूसरे कटोरे में अंडा, जूस और तेल को एक साथ फेंटें। अंडे का मिश्रण एक साथ मैदे के मिश्रण में डालें। केवल तब तक चलाएँ जब तक सब कुछ नम न हो जाए (घोल में थोड़ी गाँठें रहनी चाहिए)। कटी हुई क्रैनबेरी को धीरे से मिलाएँ।","तैयार मफिन कपों में घोल को चम्मच से भरें, हर कप को 2/3 भरें। कपों में घोल के ऊपर स्ट्रूज़ल टॉपिंग छिड़कें। 18 से 20 मिनट तक या सुनहरा होने तक और बीच में लकड़ी की टूथपिक डालने पर साफ़ निकलने तक बेक करें।","मफिन कपों में ही तार की जाली पर 5 मिनट ठंडा करें। मफिन कपों से निकालें; गरमागरम परोसें।"],
["स्ट्रूज़ल टॉपिंग वैकल्पिक है। इससे प्रति मफिन 2 ग्राम वसा और 2 ग्राम कार्बोहाइड्रेट बढ़ जाता है।","बचे हुए मफिन को फ्रीज़र या फ्रिज में रखें। परोसने से पहले माइक्रोवेव में 10 से 20 सेकंड गरम करें।"],
["1 स्टार्च","1 फल, कम पोटैशियम","1 वसा"]),
(2195,"ग्रिल की हुई समर स्क्वैश","स्वस्थ, किडनी के अनुकूल और घर पर ग्रिल की गई सब्ज़ियों से बेहतर और क्या हो सकता है? DaVita की रीनल आहार विशेषज्ञ ऐन (पेंसिल्वेनिया) आपके अगले शानदार रात के खाने का हिस्सा बनने वाली ग्रिल्ड समर स्क्वैश बनाने का आसान तरीका बता रही हैं।","8*","लगभग 4 टुकड़े (2 तोरई और 2 पीला स्क्वैश)",
["4 मध्यम तोरई","4 मध्यम क्रुकनेक स्क्वैश","नॉनस्टिक कुकिंग स्प्रे","1/4 छोटा चम्मच लहसुन पाउडर","1/4 छोटा चम्मच काली मिर्च"],
["स्क्वैश को हल्के साबुन और पानी से धोएँ; अच्छी तरह खंगाल लें।","हर स्क्वैश को चार टुकड़ों में काटें; खड़ा और आड़ा दोनों तरह से काटें।","इन्हें कुकी शीट या बड़ी थाली में रखें और नॉनस्टिक कुकिंग स्प्रे छिड़कें।","स्वादानुसार लहसुन पाउडर और काली मिर्च छिड़कें (दोनों वैकल्पिक हैं)।","George Foreman™ ग्रिल या गैस ग्रिल पर पकाएँ। Foreman™ ग्रिल इस्तेमाल करने पर लगभग तीन से पाँच मिनट पकाएँ, एक बार पलट दें। स्क्वैश नरम होना चाहिए, लेकिन गला हुआ नहीं। गैस ग्रिल पर पकाने के लिए, नॉनस्टिक कुकिंग स्प्रे लगी एल्युमिनियम फ़ॉइल की शीट पर समतल हिस्सा नीचे की ओर रखें।","मध्यम आँच पर लगभग 5 से 7 मिनट पकाएँ और ध्यान से देखते रहें। पलटें और \"गोल\" तरफ़ लगभग 2 मिनट और पकाएँ।"],
["*ध्यान दें: यह \"एक बार पकाएँ, दो बार खाएँ\" वाली रेसिपी है। इससे पहले व्यंजन के लिए 4 सर्विंग और फिर दूसरे व्यंजन के लिए 4 सर्विंग बनती हैं। वैकल्पिक रूप से, पूरी रेसिपी 8 लोगों के लिए है। \"एक बार पकाएँ, दो बार खाएँ\" के रूप में इसका उपयोग करने के लिए इटैलियन चिकन सलाद की रेसिपी देखें।","तोरई के 2 टुकड़े और पीले स्क्वैश के 2 टुकड़े रोज़मेरी-लहसुन सॉस वाले चिकन के साथ परोसें। बचा हुआ स्क्वैश इटैलियन चिकन सलाद के लिए इस्तेमाल करें; स्क्वैश के टुकड़ों को 1/4″ मोटे अर्धचंद्राकार टुकड़ों में काटें।"],
["1-1/2 सब्ज़ी, मध्यम पोटैशियम"]),
(2198,"स्ट्रूज़ल भरे सेब","ब्राउन शुगर, दालचीनी और जायफल को अखरोट और सूखी क्रैनबेरी के साथ मिलाकर बीज निकाले हुए बेकिंग सेब में भरा जाता है, जिससे ये स्वादिष्ट स्ट्रूज़ल भरे सेब बनते हैं।","2","1 सेब",
["2 मध्यम बेकिंग सेब","2 बड़े चम्मच मैदा","2 बड़े चम्मच ब्राउन शुगर","1/4 छोटा चम्मच दालचीनी","1/8 छोटा चम्मच जायफल","1 बड़ा चम्मच मक्खन","2 छोटे चम्मच कटे हुए अखरोट","2 छोटे चम्मच मीठी सूखी क्रैनबेरी"],
["ओवन को 375° F पर पहले से गरम करें। मक्खन को नरम होने के लिए बाहर रख दें।","सेबों को धोकर सुखा लें। एप्पल कोरर या तेज़ चाकू से बीज वाला हिस्सा निकाल दें, सेब का निचला हिस्सा साबुत रहने दें।","स्ट्रूज़ल बनाने के लिए एक छोटे कटोरे में मैदा, चीनी और मसाले मिलाएँ। मक्खन डालें और काँटे से मिलाएँ। कटे हुए अखरोट और क्रैनबेरी डालें।","इस मिश्रण को सेबों के अंदर भरें। हर सेब पर थोड़ा-थोड़ा मक्खन रखें।","सेबों को बेकिंग डिश में रखें। डिश में 1/2 कप उबलता पानी डालें।","सेब नरम होने तक 25 से 30 मिनट बेक करें।"],
["चाहें तो गरम सेबों के साथ थोड़ी सी व्हिप्ड क्रीम परोसें।","ग्रेस को हनीक्रिस्प सेब पसंद हैं। अन्य बेकिंग सेबों में जोनागोल्ड, ब्रेबर्न, वाइनसैप और ग्रैनी स्मिथ शामिल हैं।","कम कार्बोहाइड्रेट वाले आहार के लिए अनुशंसित मात्रा 1/2 सेब है। ब्राउन शुगर की जगह 1 बड़ा चम्मच ब्राउन शुगर ब्लेंड इस्तेमाल करें और क्रैनबेरी हटा दें, इससे स्ट्रूज़ल वाले 1/2 सेब में कार्बोहाइड्रेट घटकर 19 ग्राम और कैलोरी 174 रह जाती है।"],
["1 फल, मध्यम पोटैशियम","1 उच्च कैलोरी","1 वसा"]),
(2201,"केला चॉकलेट चिप मफिन","केला चॉकलेट चिप मफिन में प्रत्येक में 6 ग्राम प्रोटीन होता है और ये उन लोगों के लिए आदर्श नाश्ता हैं जिन्हें पोटैशियम सीमित करने के बजाय बढ़ाने की ज़रूरत है।","12","1 मफिन",
["2 बड़े पके केले (लगभग 8” लंबे)","1 कप स्मूद पीनट बटर","2 बड़े अंडे","1 छोटा चम्मच वनीला एक्सट्रैक्ट","2 बड़े चम्मच शहद","1/2 छोटा चम्मच बेकिंग सोडा","1/2 छोटा चम्मच पिसी दालचीनी","1/2 कप सेमी-स्वीट चॉकलेट चिप्स"],
["ओवन को 400° F पर पहले से गरम करें। मफिन पैन में कागज़ या सिलिकॉन के लाइनर लगाएँ।","केले छीलकर काँटे से मसल लें।","एक मध्यम कटोरे में चॉकलेट चिप्स को छोड़कर सारी सामग्री को अच्छी तरह मिलने तक फेंटें। फिर चॉकलेट चिप्स मिलाएँ।","मफिन कपों को घोल से 1/2 भरें। 15 मिनट बेक करें।","ओवन से निकालें और तार की जाली पर ठंडा करें; मफिन को पैन से निकालें और आनंद लें।"],
["ये मफिन उन किडनी रोगियों के लिए सबसे अच्छे हैं जिन्हें पोटैशियम सीमित आहार की ज़रूरत नहीं है, क्योंकि केला, पीनट बटर और चॉकलेट में पोटैशियम अधिक होता है।","अगर आप कम वसा वाला पीनट बटर इस्तेमाल करते हैं, तो प्रति सर्विंग लगभग 5 ग्राम कार्बोहाइड्रेट बढ़ जाएगा।","यह मफिन प्रोटीन से भरपूर अच्छा नाश्ता है। अगर आपके लिए फॉस्फेट बाइंडर निर्धारित है, तो अपने आहार विशेषज्ञ से पूछें कि उसे लेना ज़रूरी है या नहीं।"],
["1 प्रोटीन","1/2 फल, मध्यम पोटैशियम","1-1/2 वसा","1/2 उच्च कैलोरी"]),
(2208,"टूना प्रोटीन बेंटो लंच","प्रोटीन से भरपूर यह बेंटो बॉक्स एक प्यारे से पैकेज में पूरा भोजन है। चलते-फिरते या घर पर खाएँ।","2","1 बेंटो बॉक्स",
["4.5 ऑउंस का 1 डिब्बा टूना, बिना नमक वाला, पानी में पैक किया हुआ","1 छोटा डंठल अजवाइन (सेलरी)","2 बड़े चम्मच लाल प्याज़","1 बड़ा चम्मच मेयोनेज़","1 छोटा चम्मच लहसुन पाउडर","1 छोटा चम्मच सूखी सोया (डिल)","1/2 छोटा चम्मच प्याज़ पाउडर","10 बेबी गाजर","1 मिनी खीरा","1 सेब","2 उबले अंडे","2 राइस केक"],
["टूना को डिब्बे से निकालकर पानी निथार लें और एक छोटे मिक्सिंग बाउल में रखें। अजवाइन (सेलरी) और लाल प्याज़ को बारीक काट लें।","मेयोनेज़, कटी हुई अजवाइन (सेलरी), कटा हुआ प्याज़ और मसाले टूना वाले कटोरे में डालें। अच्छी तरह मिलाएँ।","खीरों का छिलका उतारकर उन्हें लंबे टुकड़ों में काट लें। सेब को पतले स्लाइस में काटें। अगर मिनी खीरे न मिलें, तो हर बॉक्स के लिए एक मध्यम खीरे के 5 स्लाइस इस्तेमाल करें।","दो बेंटो बॉक्स इस्तेमाल करें। आधा टूना मिश्रण, आधी गाजर और आधा खीरा बॉक्सों में रखें। अंडों को आधा काटें और हर बॉक्स में 1 अंडा और 1 राइस केक रखें।"],
["StarKist® Select ब्रांड (प्रति डिब्बा लगभग 65mg सोडियम)।","पूरी तरह उबले अंडे बनाने के लिए: अंडों को पैन में रखें और पानी से ढक दें। पानी को 5 मिनट उबलने दें, फिर गैस बंद कर दें और अंडों को 10 मिनट पानी में ही रहने दें। ठंडे पानी से धोएँ और तुरंत छील लें।","राइस केक की जगह आप मल्टी-ग्रेन क्रैकर या कॉर्न थिन्स भी इस्तेमाल कर सकते हैं। डिब्बे पर बताई गई सर्विंग के अनुसार ही खाएँ और कम सोडियम वाले विकल्प देखें।","यह पूरा भोजन माना जाता है, इसलिए पोटैशियम की मात्रा उचित सीमा के भीतर है।"],
["2-1/2 प्रोटीन","1 सब्ज़ी, मध्यम पोटैशियम","1/2 फल, कम पोटैशियम"]),
(2209,"बटरमिल्क पाई","सिर्फ़ इसलिए कि आप डायलिसिस पर हैं, इसका मतलब यह नहीं कि आप कभी-कभार मीठे का आनंद नहीं ले सकते। मिशिगन की रीनल आहार विशेषज्ञ मोनिका एक लाजवाब, किडनी के अनुकूल मिठाई की रेसिपी पेश कर रही हैं, जो अतिरिक्त कैलोरी की ज़रूरत होने पर बहुत अच्छी है।","8","पाई का 1/8 स्लाइस",
["1 कप बटरमिल्क","2 अंडे","1/4 कप मक्खन","2 बड़े चम्मच नींबू का रस","1 छोटा चम्मच बादाम एक्सट्रैक्ट","1 छोटा चम्मच वनीला एक्सट्रैक्ट","1-1/2 कप चीनी","4 बड़े चम्मच मैदा","1 डीप-डिश पाई क्रस्ट, 9 इंच का"],
["ओवन को 375° F पर पहले से गरम करें। मक्खन को नरम होने के लिए बाहर रख दें।","एक बड़े मिक्सिंग बाउल में बटरमिल्क, अंडे, नरम किया हुआ मक्खन, नींबू का रस, बादाम एक्सट्रैक्ट, वनीला एक्सट्रैक्ट, चीनी और मैदा मिलाएँ।","मिश्रण को डीप-डिश पाई क्रस्ट में डालें।","एक घंटे तक बेक करें।","ठंडा होने दें और परोसें।"],
["बटरमिल्क में फॉस्फोरस और पोटैशियम अधिक होता है, लेकिन प्रति सर्विंग मात्रा इतनी कम है कि यह रेसिपी किडनी के अनुकूल बनी रहती है।"],
["1-1/2 स्टार्च","3 वसा","1-1/2 उच्च कैलोरी"]),
(2214,"टूना के साथ इटैलियन स्टाइल मैकरोनी सलाद","पास्ता सलाद में टूना और उबले अंडे मिलाकर उच्च गुणवत्ता वाला प्रोटीन बढ़ाएँ। DaVita की आहार विशेषज्ञ लोरेन ने अपनी मरीज़ फ्रेडा को प्रेरित किया कि वे अपना टूना के साथ इटैलियन स्टाइल मैकरोनी सलाद साझा करें।","10","1 कप",
["3 बड़े अंडे","1 पाउंड छोटे शेल पास्ता, बिना पका हुआ","3 बड़े चम्मच कम वसा वाला मेयोनेज़","6 ऑउंस जैतून के तेल में डिब्बाबंद टूना","2 बड़े चम्मच गर्किन अचार","1 बड़ा चम्मच मीठे अचार का रस"],
["अंडों को पूरी तरह उबलने तक लगभग 10 मिनट उबालें। अंडों को ठंडा करने के लिए ठंडे पानी के कटोरे में रखें।","अंडे उबलते समय 1 पाउंड छोटे शेल या डिटालिनी पास्ता को अल डेंटे होने तक उबालें। पानी निथार लें।","पास्ता को एक कटोरे में डालें और मेयोनेज़ मिलाएँ।","6 ऑउंस डिब्बाबंद टूना डालें और पास्ता के साथ मिलाएँ।","कटे हुए बेबी गर्किन अचार और एक बड़ा चम्मच अचार का रस डालें; पास्ता के साथ मिलाएँ।","उबले अंडे छीलकर स्लाइस में काटें और पास्ता में डालें।","परोसने तक फ्रिज में रखें। आनंद लें!"],
["फ्रेडा Pastene® ब्रांड का इटैलियन-स्टाइल टूना (टोन्नो) इस्तेमाल करती हैं, जो जैतून के तेल में डिब्बाबंद होता है।","डिटालिनी पास्ता छोटी नलियों के आकार का पास्ता है, जिसे बहुत छोटी मैकरोनी कहा जाता है।","कम कार्बोहाइड्रेट वाले आहार के लिए मात्रा को समायोजित करें।"],
["1 प्रोटीन","2 स्टार्च"]),
(2215,"चिकन वाइल्ड राइस सूप","DaVita की मिनेसोटा की रीनल आहार विशेषज्ञ अपनी कुछ पसंदीदा क्षेत्रीय रेसिपी साझा करती हैं, जिन्हें डायलिसिस आहार के अनुसार बदला गया है। फॉस्फोरस, पोटैशियम और सोडियम को सीमित करके डायलिसिस के मरीज़ स्वादिष्ट चिकन वाइल्ड राइस सूप की इस किडनी के अनुकूल रेसिपी का आनंद ले सकते हैं।","6","1 कप",
["2/3 कप लंबे दाने वाले चावल और वाइल्ड राइस का मिश्रण, बिना पका हुआ","1 बड़ा चम्मच प्याज़, बारीक कटा हुआ","1 बड़ा चम्मच ताज़ा अजमोद (पार्सले)","1 कप गाजर","8 ऑउंस चिकन ब्रेस्ट, पका हुआ","2 बड़े चम्मच मक्खन","1/4 कप सफ़ेद मैदा","5 कप कम सोडियम वाला चिकन ब्रॉथ","1 बड़ा चम्मच पतले कटे बादाम (वैकल्पिक)"],
["चावल को 2 कप ब्रॉथ और 1/2 कप पानी के साथ मिलाएँ। राइस कुकर में या चूल्हे पर पकाएँ।","प्याज़ और अजमोद को बारीक काटें। गाजर को कद्दूकस करें। चिकन को काट लें।","सॉसपैन में मक्खन पिघलाएँ; प्याज़ डालकर नरम होने तक भूनें।","मैदा मिलाएँ; धीरे-धीरे चिकन ब्रॉथ डालें।","मध्यम आँच पर लगातार चलाते हुए पकाएँ जब तक मिश्रण थोड़ा गाढ़ा न हो जाए।","चावल, चिकन और गाजर मिलाएँ। 5 मिनट धीमी आँच पर पकाएँ।","बादाम डालें और परोसने से पहले कटे हुए अजमोद से सजाएँ।"],
["चावल को पैकेट के निर्देशों के अनुसार पकाएँ, नमक या मसाले का पैकेट अगर साथ आया हो तो उसे न डालें।"],
["2 प्रोटीन","2 स्टार्च","1 सब्ज़ी, कम पोटैशियम"]),
(2216,"फेस्टिव पाइनएप्पल चीज़ बॉल","फेस्टिव पाइनएप्पल चीज़ पार्टी में किडनी के अनुकूल एपेटाइज़र परोसने का एक स्वादिष्ट और मज़ेदार तरीका है। इस स्नैक में क्रैकर या पीटा स्नैक्स डुबोकर किडनी आहार के लिए एक लज़ीज़ व्यंजन का आनंद लिया जा सकता है।","24","2 बड़े चम्मच",
["24 ऑउंस क्रीम चीज़","20 ऑउंस डिब्बाबंद कुचला हुआ अनानास","1/2 कप हरी शिमला मिर्च","1/2 छोटा चम्मच लहसुन पाउडर"],
["क्रीम चीज़ को नरम करें और फिर एक बड़े मिक्सिंग बाउल में रखें।","अनानास का पानी अच्छी तरह निथार दें। शिमला मिर्च को काट लें।","सामग्री को कटोरे में डालें और अच्छी तरह मिलाएँ।","मिश्रण को गेंद का आकार दें। वैक्स पेपर में लपेटकर रात भर ठंडा करें।"],
["सुनिश्चित करें कि अनानास का पानी पूरी तरह निथर गया हो, ज़रूरत हो तो हाथ से दबाकर पानी निचोड़ दें।","इसे तरह-तरह के क्रैकर या पीटा चिप्स के साथ परोसें।","वसा की मात्रा घटाने के लिए कम वसा वाला क्रीम चीज़ इस्तेमाल करके देखें।"],
["1/2 दूध","1 वसा"]),
(2218,"बैंगन सीफ़ूड कैसरोल","बैंगन सीफ़ूड कैसरोल आपके अगले रात के खाने में परोसने के लिए एक स्वादिष्ट, किडनी के अनुकूल रेसिपी है।","8","1 कप",
["2 मध्यम बैंगन","1 मध्यम प्याज़","1 शिमला मिर्च","1/2 कप अजवाइन (सेलरी)","2 लहसुन की कलियाँ","1/4 कप जैतून का तेल","1/4 कप नींबू का रस","1 बड़ा चम्मच वॉर्सेस्टरशायर सॉस","1/4 छोटा चम्मच क्रियोल सीज़निंग","1/2 छोटा चम्मच Tabasco® तीखा मिर्च सॉस","1/3 कप चावल, बिना पका हुआ","1/4 कप परमेसन चीज़","1 चुटकी लाल मिर्च (केयेन)","3 बड़े अंडे","1 पाउंड लंप क्रैब मीट","1/2 पाउंड उबले झींगे","1/2 कप ब्रेड क्रम्ब्स","2 बड़े चम्मच मक्खन, पिघला हुआ"],
["ओवन को 350° F पर पहले से गरम करें।","प्याज़, शिमला मिर्च और अजवाइन (सेलरी) को काट लें। बैंगन का छिलका उतारकर 1” के टुकड़ों में काट लें।","बैंगन को मध्यम सॉसपैन में रखें, पानी से ढकें और नरम होने तक लगभग 5 मिनट उबालें। अच्छी तरह निथार लें, एक मिक्सिंग बाउल में डालें और एक तरफ़ रख दें।","प्याज़, शिमला मिर्च, अजवाइन (सेलरी) और लहसुन को जैतून के तेल में नरम होने तक भूनें, लेकिन भूरा न होने दें।","भुनी हुई सब्ज़ियों को बैंगन में धीरे से मिलाएँ। नींबू का रस, वॉर्सेस्टरशायर सॉस, क्रियोल सीज़निंग, Tabasco सॉस, चावल, परमेसन चीज़, लाल मिर्च और फेंटे हुए अंडे डालें। अच्छी तरह मिलाने के लिए चलाएँ।","सीफ़ूड को सब्ज़ी के मिश्रण में धीरे से मिलाएँ। चिकनाई लगी कैसरोल डिश में रखें।","ब्रेड क्रम्ब्स को पिघले मक्खन में मिलाएँ और कैसरोल के ऊपर फैलाएँ।","25 से 30 मिनट तक बेक करें जब तक ऊपर की परत भूरी होने न लगे।"],
["क्रियोल सीज़निंग काली और लाल मिर्च, नमक और थाइम का मिश्रण होती है। लुइज़ियाना के लोकप्रिय ब्रांडों में Tony Chachere’s® और Paul Prudhomme’s® शामिल हैं।"],
["1 प्रोटीन","1 सब्ज़ी, मध्यम पोटैशियम","1 स्टार्च","1 वसा"]),
(2219,"साउथ ऑफ़ द बॉर्डर मीटबॉल","किडनी के अनुकूल साउथ ऑफ़ द बॉर्डर मीटबॉल से अपनी रसोई में तीखापन लाएँ। यह एपेटाइज़र रेसिपी किडनी रोग, मधुमेह वाले या डायलिसिस पर रहने वाले लोगों के लिए बढ़िया है।","24 सर्विंग","2 मीटबॉल",
["1-1/2 कप प्याज़","1-1/2 कप हरी शिमला मिर्च","2 जलापेन्यो मिर्च","3 पाउंड बीफ़ कीमा","4 कप पका हुआ चावल","5 बड़े अंडे","1 बड़ा चम्मच लहसुन पाउडर","1 कप टैको सॉस","1 कप पानी"],
["ओवन को 375° F पर पहले से गरम करें।","प्याज़, हरी शिमला मिर्च और जलापेन्यो मिर्च को काट लें। अंडे फेंट लें।","एक बड़े कटोरे में बीफ़ कीमा, प्याज़, हरी शिमला मिर्च, जलापेन्यो, पका हुआ चावल, फेंटे हुए अंडे और लहसुन पाउडर को एक साथ मिलाएँ।","1” की गोलियाँ बनाकर बेकिंग शीट पर रखें।","मीटबॉल पूरी तरह पकने तक 10 से 15 मिनट बेक करें।","एक सॉसपैन में टैको सॉस और पानी मिलाकर उबाल लें।","मीटबॉल को टैको सॉस में डालें और आँच धीमी कर दें ताकि गरम बने रहें।","गरमागरम परोसें या ढके हुए वार्मिंग डिश या स्लो कुकर में धीमी आँच की सेटिंग पर रखें।"],
["मीटबॉल पहले से बनाकर फ्रिज में रखें। परोसने के समय सामग्री को एक साथ गरम करें और वार्मिंग डिश में डाल दें।","टैको सॉस का सबसे कम सोडियम वाला ब्रांड चुनें।"],
["1-1/2 प्रोटीन","1/2 स्टार्च","1/2 सब्ज़ी, कम पोटैशियम","1/2 वसा"]),
(2221,"पीच कॉबलर","किसने कहा कि मेहमानों के लायक मिठाई जटिल होनी चाहिए? DaVita की रीनल आहार विशेषज्ञ टोरी (लुइज़ियाना) एक लाजवाब पीच कॉबलर पेश कर रही हैं, जो बनाने में आसान है और किडनी के अनुकूल भी। गरम परोसें या ठंडा, यह एक स्वादिष्ट, बिना अपराधबोध वाली मीठी ट्रीट है जिसे खाकर हर कोई और माँगेगा।","12","1/2 कप",
["1 कप बादाम का दूध (ओरिजिनल फ़्लेवर)","1 कप मैदा","1/2 बड़ा चम्मच बेकिंग पाउडर","2/3 कप Splenda® नो कैलोरी स्वीटनर, दानेदार","20 ऑउंस डिब्बाबंद पीच पाई फ़िलिंग","6 बड़े चम्मच बिना नमक वाला मक्खन","1/2 छोटा चम्मच पिसी दालचीनी"],
["ओवन को 350° F पर पहले से गरम करें।","एक बड़े कटोरे में बादाम का दूध, मैदा, बेकिंग पाउडर और Splenda® (या चीनी) को चिकना होने तक मिलाएँ। एक तरफ़ रख दें।","माइक्रोवेव में रखने योग्य डिश में मक्खन पिघलाएँ और 9” x 13” की बेकिंग डिश में डाल दें।","दूध का मिश्रण सीधे बेकिंग डिश में पिघले मक्खन के ऊपर डालें।","पाई फ़िलिंग खोलें और ढेर सारे चम्मच भरकर मिश्रण के ऊपर यहाँ-वहाँ रखें।","कॉबलर के ऊपर पिसी दालचीनी छिड़कें।","लगभग 40 से 45 मिनट तक या परत के भूरी और फूली होने तक बेक करें।"],
["अलग स्वाद के लिए अपनी पसंदीदा किडनी के अनुकूल, कम पोटैशियम वाले फल की पाई फ़िलिंग इस्तेमाल करें।","दालचीनी के साथ, बेक करने से पहले कॉबलर के ऊपर अतिरिक्त Splenda® या चीनी भी छिड़क सकते हैं।"],
["1/2 फल, मध्यम पोटैशियम","1 वसा","1/2 उच्च कैलोरी"]),
(2224,"फ्रोज़न फ्रूट डेज़र्ट","DaVita की रीनल आहार विशेषज्ञ मिंडी (वर्जीनिया) एक खास फ्रोज़न फ्रूट डेज़र्ट की रेसिपी बता रही हैं। यह ताज़गी भरा व्यंजन ठंडा, फलों से भरपूर और स्वादिष्ट है। यह गर्मियों का बढ़िया स्नैक है और आइसक्रीम का किडनी के अनुकूल विकल्प है। मिठाई या स्नैक के रूप में आइसक्रीम कोन या कटोरे में परोसें।","10","1/2 कप",
["1/3 कप मराशिनो चेरी","8 ऑउंस डिब्बाबंद कुचला हुआ अनानास","8 ऑउंस कम वसा वाली खट्टी क्रीम (सावर क्रीम)","1 बड़ा चम्मच नींबू का रस","1 कप कटी हुई स्ट्रॉबेरी","1/2 कप चीनी","1/8 छोटा चम्मच नमक","3 कप Reddi-Wip® डेयरी व्हिप्ड टॉपिंग"],
["चेरी को काट लें और अनानास का पानी निथार दें।","व्हिप्ड टॉपिंग को छोड़कर सारी सामग्री को एक मध्यम कटोरे में डालें और अच्छी तरह मिलाएँ। फिर व्हिप्ड टॉपिंग को धीरे से मिलाएँ।","मिश्रण को फ्रीज़ करने योग्य प्लास्टिक के डिब्बे में डालें और 2 से 3 घंटे तक जमने दें।"],
["अगर आपको मधुमेह है, तो चीनी की जगह 1/2 कप Splenda® दानेदार स्वीटनर या 12 पैकेट टेबलटॉप कम कैलोरी वाला स्वीटनर इस्तेमाल करें। कार्बोहाइड्रेट घटकर 13 ग्राम रह जाता है और कार्बोहाइड्रेट चॉइस एक हो जाती है।","आकर्षक प्रस्तुति के लिए मराशिनो चेरी के आधे टुकड़ों से सजाएँ।","आप ताज़ी या जमी हुई स्ट्रॉबेरी इस्तेमाल कर सकते हैं।"],
["1 फल, कम पोटैशियम","1 वसा","1/2 उच्च कैलोरी"]),
(2226,"अंजीर और बकरी के चीज़ वाली क्रोस्टिनी","इस आसानी से बनने वाले अंजीर और बकरी के चीज़ वाली क्रोस्टिनी एपेटाइज़र से अपने त्योहार के मेहमानों को चौंका दें।","12","2 टुकड़े",
["1 फ्रेंच बैगेट","1/4 कप बिना नमक वाला मक्खन","1/4 कप जैतून का तेल","1/2 कप बकरी के चीज़ का चूरा","1/2 कप अंजीर का स्प्रेड या प्रिज़र्व","2 बड़े चम्मच बालसमिक सिरके का ग्लेज़"],
["ओवन को 375° F पर पहले से गरम करें। बैगेट को 24 स्लाइस में काटें, हर स्लाइस 1/2 इंच मोटा।","क्रोस्टिनी बनाने के लिए मक्खन पिघलाएँ; उसमें जैतून का तेल मिलाएँ। ब्रेड के हर स्लाइस के दोनों तरफ़ यह मिश्रण लगाएँ और बेकिंग शीट पर रखें।","क्रोस्टिनी को 5-7 मिनट बेक करें। स्लाइस पलटें और कुरकुरा और सुनहरा भूरा होने तक 5 मिनट और बेक करें।","हर क्रोस्टिनी पर 1 छोटा चम्मच अंजीर का स्प्रेड लगाएँ। ऊपर से 1 छोटा चम्मच बकरी के चीज़ का चूरा छिड़कें। सभी क्रोस्टिनी तैयार हो जाने के बाद बालसमिक सिरके का ग्लेज़ ऊपर से डालें।"],
["अंजीर का बटर, अंजीर का स्प्रेड, अंजीर का प्रिज़र्व या सूखे या ताज़े अंजीर इस्तेमाल करें।","बकरी के चीज़ के चूरे की जगह नरम बकरी का चीज़ इस्तेमाल किया जा सकता है। इसे क्रोस्टिनी पर लगाएँ, फिर अंजीर का प्रिज़र्व और बालसमिक सिरके का ग्लेज़ डालें।","अगर बालसमिक सिरके का ग्लेज़ उपलब्ध न हो, तो पुराने इटैलियन बालसमिक सिरके को गरम करके आधा होने तक गाढ़ा करके ग्लेज़ बना सकते हैं।"],
["1/2 स्टार्च","1/2 फल, कम पोटैशियम","2 वसा"]),
(2229,"पंपकिन पुडिंग","अगर आप स्वादिष्ट तरीके से प्रोटीन बढ़ाने का कोई उपाय खोज रहे हैं, तो DaVita की आहार विशेषज्ञ जूलिया के पास बिल्कुल सही जवाब है। पंपकिन पुडिंग आज़माएँ, जो पुडिंग मिक्स, प्रोटीन पाउडर और बादाम के दूध का मिश्रण है और जिसमें कद्दू पाई के मसालों का स्वाद है।","4","1/2 कप",
["3 ऑउंस का 1 डिब्बा कुक एंड सर्व वनीला पुडिंग मिक्स","1 2/3 कप बादाम का दूध, बिना फ़ोर्टिफ़ाइड","1 छोटा चम्मच कद्दू पाई मसाला (पंपकिन पाई स्पाइस)","1 स्कूप व्हे प्रोटीन पाउडर"],
["एक मध्यम सॉसपैन में पुडिंग मिक्स और बादाम का दूध मिलाएँ।","मध्यम आँच पर लगातार चलाते हुए उबालें। पुडिंग के गाढ़ा होने तक चलाते रहें।","आँच से उतारें और प्रोटीन पाउडर और कद्दू पाई मसाला मिलाएँ। पूरी तरह मिलाएँ।","प्लास्टिक रैप को सीधे पुडिंग की सतह पर रखें और फ्रिज में कम से कम 3 घंटे या रात भर ठंडा करें। ठंडा होने पर पुडिंग गाढ़ा हो जाएगा।","ठंडी पुडिंग को परोसने से पहले चला लें।"],
["विविधता के लिए पुडिंग मिक्स का फ़्लेवर बदलें।","व्हे प्रोटीन पाउडर मिलाने से प्रोटीन की मात्रा दूध से बनी पुडिंग के समान हो जाती है।","प्रोटीन पाउडर के स्कूप का आकार और प्रोटीन की मात्रा अलग-अलग होती है। विश्लेषण में EAS व्हे प्रोटीन पाउडर इस्तेमाल किया गया है।","इंस्टेंट पुडिंग मिक्स का इस्तेमाल न करें। उसमें सोडियम बहुत अधिक होता है।"],
["1 स्टार्च","1/2 दूध का विकल्प"]),
]
